 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelRotaryMul {
public:
    __aicore__ inline KernelRotaryMul() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t lastDim, int64_t mode)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
            r1Gm.SetGlobalBuffer((__gm__ T *)r1 + offset, formerLength);
            r2Gm.SetGlobalBuffer((__gm__ T *)r2 + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
            r1Gm.SetGlobalBuffer((__gm__ T *)r1 + offset, tailLength);
            r2Gm.SetGlobalBuffer((__gm__ T *)r2 + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->lastDim = lastDim;
        this->mode = mode;

        pipe.InitBuffer(inQueueInput, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueR1, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueR2, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(half)) {
            pipe.InitBuffer(calcBuf, tileLength * sizeof(float));
            pipe.InitBuffer(calcBufR1, tileLength * sizeof(float));
            pipe.InitBuffer(calcBufR2, tileLength * sizeof(float));
            pipe.InitBuffer(calcBufOut, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> inputLocal = inQueueInput.AllocTensor<T>();
        AscendC::LocalTensor<T> r1Local = inQueueR1.AllocTensor<T>();
        AscendC::LocalTensor<T> r2Local = inQueueR2.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(inputLocal, inputGm[progress * this->tileLength], copyParams);
        AscendC::DataCopyPad(r1Local, r1Gm[progress * this->tileLength], copyParams);
        AscendC::DataCopyPad(r2Local, r2Gm[progress * this->tileLength], copyParams);

        inQueueInput.EnQue(inputLocal);
        inQueueR1.EnQue(r1Local);
        inQueueR2.EnQue(r2Local);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> inputLocal = inQueueInput.DeQue<T>();
        AscendC::LocalTensor<T> r1Local = inQueueR1.DeQue<T>();
        AscendC::LocalTensor<T> r2Local = inQueueR2.DeQue<T>();
        AscendC::LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();

        int64_t baseOffset = progress * this->tileLength;

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 direct computation
            for (int64_t idx = 0; idx < curTileLength; ++idx) {
                int64_t globalIdx = baseOffset + idx;
                int64_t lastPos = globalIdx % this->lastDim;
                int64_t rotatedIdx;

                if (this->mode == 0) {
                    // half mode
                    int64_t halfD = this->lastDim / 2;
                    if (lastPos < halfD) {
                        rotatedIdx = globalIdx + halfD;
                    } else {
                        rotatedIdx = globalIdx - halfD;
                    }
                } else {
                    // interleave mode
                    if (lastPos % 2 == 0) {
                        rotatedIdx = globalIdx + 1;
                    } else {
                        rotatedIdx = globalIdx - 1;
                    }
                }

                // Ensure rotatedIdx is within the block
                if (rotatedIdx >= this->blockLength) {
                    rotatedIdx = globalIdx;
                }

                float inputVal = inputLocal.GetValue(idx);
                float rotatedVal = inputLocal.GetValue(rotatedIdx - baseOffset);
                float r1Val = r1Local.GetValue(idx);
                float r2Val = r2Local.GetValue(idx);

                float result = inputVal * r1Val + (-rotatedVal) * r2Val;
                outputLocal.SetValue(idx, result);
            }
        } else {
            // FP16/BF16: cast to FP32, compute, cast back
            AscendC::LocalTensor<float> inputFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> r1Fp32 = calcBufR1.Get<float>();
            AscendC::LocalTensor<float> r2Fp32 = calcBufR2.Get<float>();
            AscendC::LocalTensor<float> outFp32 = calcBufOut.Get<float>();

            AscendC::Cast(inputFp32, inputLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(r1Fp32, r1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(r2Fp32, r2Local, AscendC::RoundMode::CAST_NONE, curTileLength);

            for (int64_t idx = 0; idx < curTileLength; ++idx) {
                int64_t globalIdx = baseOffset + idx;
                int64_t lastPos = globalIdx % this->lastDim;
                int64_t rotatedIdx;

                if (this->mode == 0) {
                    // half mode
                    int64_t halfD = this->lastDim / 2;
                    if (lastPos < halfD) {
                        rotatedIdx = globalIdx + halfD;
                    } else {
                        rotatedIdx = globalIdx - halfD;
                    }
                } else {
                    // interleave mode
                    if (lastPos % 2 == 0) {
                        rotatedIdx = globalIdx + 1;
                    } else {
                        rotatedIdx = globalIdx - 1;
                    }
                }

                // Ensure rotatedIdx is within the block
                if (rotatedIdx >= this->blockLength) {
                    rotatedIdx = globalIdx;
                }

                float inputVal = inputFp32.GetValue(idx);
                float rotatedVal = inputFp32.GetValue(rotatedIdx - baseOffset);
                float r1Val = r1Fp32.GetValue(idx);
                float r2Val = r2Fp32.GetValue(idx);

                float result = inputVal * r1Val + (-rotatedVal) * r2Val;
                outFp32.SetValue(idx, result);
            }

            AscendC::Cast(outputLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        outQueue.EnQue<T>(outputLocal);
        inQueueInput.FreeTensor(inputLocal);
        inQueueR1.FreeTensor(r1Local);
        inQueueR2.FreeTensor(r2Local);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> outputLocal = outQueue.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outputGm[progress * this->tileLength], outputLocal, copyParams);
        outQueue.FreeTensor(outputLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueInput;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueR1;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueR2;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufR1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufR2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufOut;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> r1Gm;
    AscendC::GlobalTensor<T> r2Gm;
    AscendC::GlobalTensor<T> outputGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t lastDim;
    int64_t mode;
};

extern "C" __global__ __aicore__ void RotaryMul(GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
                                                   int64_t formerNum, int64_t formerLength,
                                                   int64_t tailLength, int64_t tileLength,
                                                   int64_t lastDim, int64_t mode,
                                                   int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelRotaryMul<half> op;
        op.Init(input, r1, r2, output, formerNum, formerLength, tailLength, tileLength, lastDim, mode);
        op.Process();
    } else {
        KernelRotaryMul<float> op;
        op.Init(input, r1, r2, output, formerNum, formerLength, tailLength, tileLength, lastDim, mode);
        op.Process();
    }
}
