#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_RotaryMul.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor RotaryMul(const at::Tensor &input, const at::Tensor &r1,
                     const at::Tensor &r2, const std::string &rotary_mode)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input.scalar_type() == r1.scalar_type(),
                "RotaryMul: input and r1 must have the same dtype");
    TORCH_CHECK(input.scalar_type() == r2.scalar_type(),
                "RotaryMul: input and r2 must have the same dtype");
    TORCH_CHECK(input.dim() == 4, "RotaryMul: input must be 4D");
    TORCH_CHECK(r1.dim() == 4, "RotaryMul: r1 must be 4D");
    TORCH_CHECK(r2.dim() == 4, "RotaryMul: r2 must be 4D");
    TORCH_CHECK(rotary_mode == "half" || rotary_mode == "interleave",
                "RotaryMul: rotary_mode must be 'half' or 'interleave'");

    at::Tensor output = at::empty_like(input);

    int64_t totalLength = input.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input.element_size();
    int64_t lastDim = input.size(-1);
    int64_t mode = (rotary_mode == "half") ? 0 : 1;

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // RotaryMul: 3 inputs + 1 output, with FP32 calc buffers for FP16/BF16
    // FP32: 3 inQueue * 2(double buf) * 4B + 1 outQueue * 2(double buf) * 4B + 1 temp * 4B = 36 * tileLength
    // FP16/BF16: 3 inQueue * 2(double buf) * 2B + 1 outQueue * 2(double buf) * 2B + 4 temp * 4B = 32 * tileLength
    int64_t bufferCoefficient;
    if (dtypeSize == 4) {
        bufferCoefficient = 36;
    } else {
        bufferCoefficient = 32;
    }
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // Ensure tileLength is a multiple of lastDim to avoid cross-tile rotated access
    if (tileLength < lastDim) {
        tileLength = lastDim;
        // Re-align to 32 bytes
        tileLength = ((tileLength + alignElements - 1) / alignElements) * alignElements;
    } else {
        tileLength = (tileLength / lastDim) * lastDim;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- EXEC_KERNEL_CMD: all arguments must be lvalues ----
    int64_t lastDimLval = lastDim;
    int64_t modeLval = mode;
    int64_t dtypeSizeLval = dtypeSize;

    EXEC_KERNEL_CMD(RotaryMul, blockDim,
                    input, r1, r2, output,
                    formerNum, formerLength, tailLength, tileLength,
                    lastDimLval, modeLval, dtypeSizeLval);

    return output;
}

}  // namespace ascend_kernel
