37	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
38	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
39	            r1Gm.SetGlobalBuffer((__gm__ T *)r1 + offset, tailLength);
