99	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
100	    {
101	        AscendC::LocalTensor<T> inputLocal = inQueueInput.DeQue<T>();
102	        AscendC::LocalTensor<T> r1Local = inQueueR1.DeQue<T>();
103	        AscendC::LocalTensor<T> r2Local = inQueueR2.DeQue<T>();
104	        AscendC::LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
105	
106	        int64_t baseOffset = progress * this->tileLength;
107	
108	        if constexpr (sizeof(T) == sizeof(float)) {
109	            // FP32 direct computation
110	            for (int64_t idx = 0; idx < curTileLength; ++idx) {
111	                int64_t globalIdx = baseOffset + idx;
112	                int64_t lastPos = globalIdx % this->lastDim;
113	                int64_t rotatedIdx;
114	
115	                if (this->mode == 0) {
116	                    // half mode
117	                    int64_t halfD = this->lastDim / 2;
118	                    if (lastPos < halfD) {
119	                        rotatedIdx = globalIdx + halfD;
120	                    } else {
121	                        rotatedIdx = globalIdx - halfD;
122	                    }
123	                } else {
124	                    // interleave mode
125	                    if (lastPos % 2 == 0) {
126	                        rotatedIdx = globalIdx + 1;
127	                    } else {
128	                        rotatedIdx = globalIdx - 1;
129	                    }
130	                }
131	
132	                // Ensure rotatedIdx is within the block
133	                if (rotatedIdx >= this->blockLength) {
134	                    rotatedIdx = globalIdx;
135	                }
136	
137	                float inputVal = inputLocal.GetValue(idx);
138	                float rotatedVal = inputLocal.GetValue(rotatedIdx - baseOffset);
139	                float r1Val = r1Local.GetValue(idx);
140	                float r2Val = r2Local.GetValue(idx);
141	
142	                float result = inputVal * r1Val + (-rotatedVal) * r2Val;
143	                outputLocal.SetValue(idx, result);
144	            }
145	        } else {
