147	            AscendC::LocalTensor<float> inputFp32 = calcBuf.Get<float>();
148	            AscendC::LocalTensor<float> r1Fp32 = calcBufR1.Get<float>();
149	            AscendC::LocalTensor<float> r2Fp32 = calcBufR2.Get<float>();
150	            AscendC::LocalTensor<float> outFp32 = calcBufOut.Get<float>();
151	
152	            AscendC::Cast(inputFp32, inputLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
153	            AscendC::Cast(r1Fp32, r1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
154	            AscendC::Cast(r2Fp32, r2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
155	
156	            for (int64_t idx = 0; idx < curTileLength; ++idx) {
157	                int64_t globalIdx = baseOffset + idx;
158	                int64_t lastPos = globalIdx % this->lastDim;
159	                int64_t rotatedIdx;
160	
161	                if (this->mode == 0) {
162	                    // half mode
163	                    int64_t halfD = this->lastDim / 2;
164	                    if (lastPos < halfD) {
165	                        rotatedIdx = globalIdx + halfD;
166	                    } else {
167	                        rotatedIdx = globalIdx - halfD;
168	                    }
169	                } else {
170	                    // interleave mode
171	                    if (lastPos % 2 == 0) {
172	                        rotatedIdx = globalIdx + 1;
173	                    } else {
174	                        rotatedIdx = globalIdx - 1;
175	                    }
176	                }
177	
178	                // Ensure rotatedIdx is within the block
179	                if (rotatedIdx >= this->blockLength) {
180	                    rotatedIdx = globalIdx;
181	                }
182	
183	                float inputVal = inputFp32.GetValue(idx);
184	                float rotatedVal = inputFp32.GetValue(rotatedIdx - baseOffset);
185	                float r1Val = r1Fp32.GetValue(idx);
186	                float r2Val = r2Fp32.GetValue(idx);
187	
188	                float result = inputVal * r1Val + (-rotatedVal) * r2Val;
189	                outFp32.SetValue(idx, result);
190	            }
191	
192	            AscendC::Cast(outputLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
193	        }
194	
195	        outQueue.EnQue<T>(outputLocal);
196	        inQueueInput.FreeTensor(inputLocal);
197	        inQueueR1.FreeTensor(r1Local);
198	        inQueueR2.FreeTensor(r2Local);
199	    }
