202	    {
203	        AscendC::LocalTensor<T> outputLocal = outQueue.DeQue<T>();
204	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T) / 32), 0, 0};
