17	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
18	
19	at::Tensor RotaryMul(const at::Tensor &input, const at::Tensor &r1,
20	                     const at::Tensor &r2, const std::string &rotary_mode)
21	{
22	    // ---- 输入校验 ----
23	    TORCH_CHECK(input.scalar_type() == r1.scalar_type(),
24	                "RotaryMul: input and r1 must have the same dtype");
25	    TORCH_CHECK(input.scalar_type() == r2.scalar_type(),
26	                "RotaryMul: input and r2 must have the same dtype");
27	    TORCH_CHECK(input.dim() == 4, "RotaryMul: input must be 4D");
28	    TORCH_CHECK(r1.dim() == 4, "RotaryMul: r1 must be 4D");
29	    TORCH_CHECK(r2.dim() == 4, "RotaryMul: r2 must be 4D");
30	    TORCH_CHECK(rotary_mode == "half" || rotary_mode == "interleave",
31	                "RotaryMul: rotary_mode must be 'half' or 'interleave'");
32	
33	    at::Tensor output = at::empty_like(input);
34	
35	    int64_t totalLength = input.numel();
36	    if (totalLength == 0) {
37	        return output;
38	    }
39	
40	    int64_t dtypeSize = input.element_size();
41	    int64_t lastDim = input.size(-1);
42	    int64_t mode = (rotary_mode == "half") ? 0 : 1;
43	
44	    // ---- 获取硬件参数 ----
45	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
46	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
47	    uint64_t ubSize;
48	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
49	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
50	
51	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
52	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
53	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
54	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
55	
56	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
57	    int64_t formerNum = usedCoreNum - 1;
58	    int64_t formerLength = totalLengthCoreAlign;
59	    int64_t tailLength = totalLength - formerNum * formerLength;
60	
61	    // ---- UB 级 tiling (核内切分) ----
62	    // RotaryMul: 3 inputs + 1 output, with FP32 calc buffers for FP16/BF16
63	    // FP32: 3 inQueue * 2(double buf) * 4B + 1 outQueue * 2(double buf) * 4B + 1 temp * 4B = 36 * tileLength
64	    // FP16/BF16: 3 inQueue * 2(double buf) * 2B + 1 outQueue * 2(double buf) * 2B + 4 temp * 4B = 32 * tileLength
65	    int64_t bufferCoefficient;
66	    if (dtypeSize == 4) {
67	        bufferCoefficient = 36;
68	    } else {
69	        bufferCoefficient = 32;
70	    }
71	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
72	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
73	    if (dtypeSize == 0) { dtypeSize = 1; }
74	    int64_t alignElements = 32 / dtypeSize;
75	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
76	
77	    // Ensure tileLength is a multiple of lastDim to avoid cross-tile rotated access
78	    if (tileLength < lastDim) {
79	        tileLength = lastDim;
80	        // Re-align to 32 bytes
81	        tileLength = ((tileLength + alignElements - 1) / alignElements) * alignElements;
82	    } else {
83	        tileLength = (tileLength / lastDim) * lastDim;
84	    }
85	
86	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
87	
88	    // ---- EXEC_KERNEL_CMD: all arguments must be lvalues ----
89	    int64_t lastDimLval = lastDim;
90	    int64_t modeLval = mode;
91	    int64_t dtypeSizeLval = dtypeSize;
92	
93	    EXEC_KERNEL_CMD(RotaryMul, blockDim,
94	                    input, r1, r2, output,
95	                    formerNum, formerLength, tailLength, tileLength,
96	                    lastDimLval, modeLval, dtypeSizeLval);
97	
98	    return output;
99	}
