13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelRotaryMul {
17	public:
18	    __aicore__ inline KernelRotaryMul() {}
19	
20	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength,
23	                                int64_t lastDim, int64_t mode)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
31	            r1Gm.SetGlobalBuffer((__gm__ T *)r1 + offset, formerLength);
32	            r2Gm.SetGlobalBuffer((__gm__ T *)r2 + offset, formerLength);
33	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
34	        } else {
35	            this->blockLength = tailLength;
36	            int64_t tailIdx = blockIdx - formerNum;
37	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
38	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
39	            r1Gm.SetGlobalBuffer((__gm__ T *)r1 + offset, tailLength);
40	            r2Gm.SetGlobalBuffer((__gm__ T *)r2 + offset, tailLength);
41	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
42	        }
43	
44	        this->tileLength = tileLength;
45	        this->lastDim = lastDim;
46	        this->mode = mode;
47	
48	        pipe.InitBuffer(inQueueInput, BUFFER_NUM, tileLength * sizeof(T));
49	        pipe.InitBuffer(inQueueR1, BUFFER_NUM, tileLength * sizeof(T));
50	        pipe.InitBuffer(inQueueR2, BUFFER_NUM, tileLength * sizeof(T));
51	        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));
52	
53	        if constexpr (sizeof(T) == sizeof(half)) {
54	            pipe.InitBuffer(calcBuf, tileLength * sizeof(float));
55	            pipe.InitBuffer(calcBufR1, tileLength * sizeof(float));
56	            pipe.InitBuffer(calcBufR2, tileLength * sizeof(float));
57	            pipe.InitBuffer(calcBufOut, tileLength * sizeof(float));
58	        }
59	    }
60	
61	    __aicore__ inline void Process()
62	    {
63	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
64	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
65	
66	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
67	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
68	
69	        for (int64_t i = 0; i < tileNum - 1; ++i) {
70	            CopyIn(i, this->tileLength);
71	            Compute(i, this->tileLength);
72	            CopyOut(i, this->tileLength);
73	        }
74	        if (tileNum > 0) {
75	            // For the last tile, use aligned length for DMA but actual length for compute
76	            CopyIn(tileNum - 1, alignedTailLen);
77	            Compute(tileNum - 1, tailTileLength);
78	            CopyOut(tileNum - 1, alignedTailLen);
79	        }
80	    }
81	
82	private:
83	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
84	    {
85	        AscendC::LocalTensor<T> inputLocal = inQueueInput.AllocTensor<T>();
86	        AscendC::LocalTensor<T> r1Local = inQueueR1.AllocTensor<T>();
87	        AscendC::LocalTensor<T> r2Local = inQueueR2.AllocTensor<T>();
88	
89	        // DataCopyPad with DataCopyParams: blockLen is in bytes (not 32B DataBlocks)
90	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0};
91	        AscendC::DataCopyPadParams padParams{false, 0, 0, 0};
92	        AscendC::DataCopyPad(inputLocal, inputGm[progress * this->tileLength], copyParams, padParams);
93	        AscendC::DataCopyPad(r1Local, r1Gm[progress * this->tileLength], copyParams, padParams);
94	        AscendC::DataCopyPad(r2Local, r2Gm[progress * this->tileLength], copyParams, padParams);
95	
96	        inQueueInput.EnQue(inputLocal);
97	        inQueueR1.EnQue(r1Local);
98	        inQueueR2.EnQue(r2Local);
99	    }
100	
101	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
102	    {
103	        AscendC::LocalTensor<T> inputLocal = inQueueInput.DeQue<T>();
104	        AscendC::LocalTensor<T> r1Local = inQueueR1.DeQue<T>();
105	        AscendC::LocalTensor<T> r2Local = inQueueR2.DeQue<T>();
106	        AscendC::LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
107	
108	        int64_t baseOffset = progress * this->tileLength;
109	
110	        if constexpr (sizeof(T) == sizeof(float)) {
111	            // FP32 direct computation
112	            for (int64_t idx = 0; idx < curTileLength; ++idx) {
113	                int64_t globalIdx = baseOffset + idx;
114	                int64_t lastPos = globalIdx % this->lastDim;
115	                int64_t rotatedLocalIdx;
116	                bool needNegate;
117	
118	                if (this->mode == 0) {
119	                    // half mode
120	                    int64_t halfD = this->lastDim / 2;
121	                    if (lastPos < halfD) {
122	                        rotatedLocalIdx = idx + halfD;
123	                        needNegate = true;
124	                    } else {
125	                        rotatedLocalIdx = idx - halfD;
126	                        needNegate = false;
127	                    }
128	                } else {
129	                    // interleave mode
130	                    if (lastPos % 2 == 0) {
131	                        rotatedLocalIdx = idx + 1;
132	                        needNegate = true;
133	                    } else {
134	                        rotatedLocalIdx = idx - 1;
135	                        needNegate = false;
136	                    }
137	                }
138	
139	                // Ensure rotatedLocalIdx is within the current tile's valid data
140	                if (rotatedLocalIdx < 0 || rotatedLocalIdx >= curTileLength) {
141	                    rotatedLocalIdx = idx;
142	                    needNegate = false;
143	                }
144	
145	                float inputVal = inputLocal.GetValue(idx);
146	                float rotatedVal = inputLocal.GetValue(rotatedLocalIdx);
147	                float r1Val = r1Local.GetValue(idx);
148	                float r2Val = r2Local.GetValue(idx);
149	
150	                float rotatedContrib = needNegate ? (-rotatedVal) * r2Val : rotatedVal * r2Val;
151	                float result = inputVal * r1Val + rotatedContrib;
152	                outputLocal.SetValue(idx, result);
153	            }
154	        } else {
155	            // FP16/BF16: cast to FP32, compute, cast back
156	            AscendC::LocalTensor<float> inputFp32 = calcBuf.Get<float>();
157	            AscendC::LocalTensor<float> r1Fp32 = calcBufR1.Get<float>();
158	            AscendC::LocalTensor<float> r2Fp32 = calcBufR2.Get<float>();
159	            AscendC::LocalTensor<float> outFp32 = calcBufOut.Get<float>();
160	
161	            AscendC::Cast(inputFp32, inputLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
162	            AscendC::Cast(r1Fp32, r1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
163	            AscendC::Cast(r2Fp32, r2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
164	
165	            for (int64_t idx = 0; idx < curTileLength; ++idx) {
166	                int64_t globalIdx = baseOffset + idx;
167	                int64_t lastPos = globalIdx % this->lastDim;
168	                int64_t rotatedLocalIdx;
169	                bool needNegate;
170	
171	                if (this->mode == 0) {
172	                    // half mode
173	                    int64_t halfD = this->lastDim / 2;
174	                    if (lastPos < halfD) {
175	                        rotatedLocalIdx = idx + halfD;
176	                        needNegate = true;
177	                    } else {
178	                        rotatedLocalIdx = idx - halfD;
179	                        needNegate = false;
180	                    }
181	                } else {
182	                    // interleave mode
183	                    if (lastPos % 2 == 0) {
184	                        rotatedLocalIdx = idx + 1;
185	                        needNegate = true;
186	                    } else {
187	                        rotatedLocalIdx = idx - 1;
188	                        needNegate = false;
189	                    }
190	                }
191	
192	                // Ensure rotatedLocalIdx is within the current tile's valid data
193	                if (rotatedLocalIdx < 0 || rotatedLocalIdx >= curTileLength) {
194	                    rotatedLocalIdx = idx;
195	                    needNegate = false;
196	                }
197	
198	                float inputVal = inputFp32.GetValue(idx);
199	                float rotatedVal = inputFp32.GetValue(rotatedLocalIdx);
200	                float r1Val = r1Fp32.GetValue(idx);
201	                float r2Val = r2Fp32.GetValue(idx);
202	
203	                float rotatedContrib = needNegate ? (-rotatedVal) * r2Val : rotatedVal * r2Val;
204	                float result = inputVal * r1Val + rotatedContrib;
205	                outFp32.SetValue(idx, result);
206	            }
207	
208	            AscendC::Cast(outputLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
209	        }
210	
211	        outQueue.EnQue<T>(outputLocal);
212	        inQueueInput.FreeTensor(inputLocal);
213	        inQueueR1.FreeTensor(r1Local);
214	        inQueueR2.FreeTensor(r2Local);
215	    }
216	
217	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
218	    {
219	        AscendC::LocalTensor<T> outputLocal = outQueue.DeQue<T>();
220	        // DataCopyPad with DataCopyParams: blockLen is in bytes (not 32B DataBlocks)
221	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0};
222	        AscendC::DataCopyPad(outputGm[progress * this->tileLength], outputLocal, copyParams);
223	        outQueue.FreeTensor(outputLocal);
224	    }
225	
226	private:
227	    AscendC::TPipe pipe;
228	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueInput;
229	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueR1;
230	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueR2;
231	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
232	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
233	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufR1;
234	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufR2;
235	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBufOut;
236	    AscendC::GlobalTensor<T> inputGm;
237	    AscendC::GlobalTensor<T> r1Gm;
238	    AscendC::GlobalTensor<T> r2Gm;
239	    AscendC::GlobalTensor<T> outputGm;
240	    int64_t blockLength;
241	    int64_t tileLength;
242	    int64_t lastDim;
243	    int64_t mode;
244	};
245	
246	extern "C" __global__ __aicore__ void RotaryMul(GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
247	                                                   int64_t formerNum, int64_t formerLength,
248	                                                   int64_t tailLength, int64_t tileLength,
249	                                                   int64_t lastDim, int64_t mode,
250	                                                   int64_t dtypeSize)
251	{
252	    if (dtypeSize == 2) {
253	        KernelRotaryMul<half> op;
254	        op.Init(input, r1, r2, output, formerNum, formerLength, tailLength, tileLength, lastDim, mode);
255	        op.Process();
256	    } else {
257	        KernelRotaryMul<float> op;
258	        op.Init(input, r1, r2, output, formerNum, formerLength, tailLength, tileLength, lastDim, mode);
259	        op.Process();
260	    }
261	}
